import{_ as s,l as i,o as e,c as o,v as t,p as n,x as r,d,i as A,S as h}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"DH 与 RSA 分工","description":"","frontmatter":{"title":"DH 与 RSA 分工","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dh-vs-rsa.md","filePath":"cs/dh-vs-rsa.md","lastUpdated":1789023840000}'),p={name:"cs/dh-vs-rsa.md"};function D(E,a,c,_,S,m){const l=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="dh-与-rsa-分工" tabindex="-1">DH 与 RSA 分工 <a class="header-anchor" href="#dh-与-rsa-分工" aria-label="Permalink to &quot;DH 与 RSA 分工&quot;">​</a></h1><div class="epigraph"><p>DH 让双方在公开信道上得到共享秘密；RSA 加密能封住一段会话键。当代握手多把认证与封装拆开，而不是一种算法包办。</p><footer>—— Diffie and Hellman, 1976；Rivest, Shamir and Adleman, 1978；RFC 8446 的分工对照</footer></div><p><a href="/cs/pubkey-envelope">上一课</a>给出信封：公钥运对称键。本课不重画「大数据走对称」。缺口是两种常见公钥活：Diffie–Hellman 密钥协商与 RSA 加密封装（历史上还有 RSA 签名）。哈希与碰撞下一课才进完整性原语。中间人若无认证，DH 会对错误对端成功——后课证书收口。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>信封课把公钥当「能封」。实践有两条路。DH（及椭圆曲线变体）：双方临时公钥，导出共享秘密，再派生 AEAD 键；认证另用签名。RSA 加密：用对端长期公钥封随机会话键。RFC 8446 去掉 RSA 密钥传输，保留（EC）DHE + 签名。缺口是<strong>协商对封装的分工</strong>，不是数论证明。</p><p><span class="marginnote">前向保密：临时 DH 使长期签名钥泄露不解密过去会话。静态 RSA 封装通常没有这层。这是机制，不是配置命令。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>TLS 1.3：Hello 带密钥份额，共享秘密进 HKDF，证书链验证签名。应用若自造协议，不要把「RSA 加密一段口令」当会话。本课不给参数选择菜谱，只要求认清哪一步做认证、哪一步做密钥。</p>',8)),(e(),n(h,null,{default:r(()=>[A(l,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DH%5B%22%E4%B8%B4%E6%97%B6%20DH%20%E4%BB%BD%E9%A2%9D%22%5D%20--%3E%20SS%5B%22%E5%85%B1%E4%BA%AB%E7%A7%98%E5%AF%86%22%5D%0A%20%20SIG%5B%22%E8%AF%81%E4%B9%A6%E4%B8%8A%E7%9A%84%E7%AD%BE%E5%90%8D%22%5D%20--%3E%20AUTH%5B%22%E8%AE%A4%E8%AF%81%E5%AF%B9%E7%AB%AF%22%5D%0A%20%20SS%20--%3E%20KDF%5B%22%E6%B4%BE%E7%94%9F%20AEAD%20%E9%94%AE%22%5D%0A%20%20AUTH%20--%3E%20KDF%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分工避免一把长期加密钥既认证又解密历史。DY 模型里未认证的 DH 只得到「与某匿名对端的共享秘密」。后课 PKI 把名字绑到验证密钥。哈希课提供签名要吃的摘要。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入后量子封装算法当主干必选。摘要为何要抗碰撞，下一课哈希。</p><p>后课默认：会话键来自 DH 类协商加认证。完整性原语从哈希开始。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DH 协商共享秘密；RSA 曾用于封装，TLS 1.3 不再做密钥传输。</li><li>认证与封装分开才有前向保密。</li><li>哈希与碰撞下一课。</li><li>出处：Diffie–Hellman 1976；RSA 1978；RFC 8446。</li></ul>',7))])}const u=s(p,[["render",D]]);export{B as __pageData,u as default};
